import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.TQKaXlFR.js";const E=JSON.parse('{"title":"错误码与失败恢复","description":"","frontmatter":{},"headers":[],"relativePath":"reference/error-codes.md","filePath":"reference/error-codes.md"}'),r={name:"reference/error-codes.md"};function i(s,t,c,n,l,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="错误码与失败恢复" tabindex="-1">错误码与失败恢复 <a class="header-anchor" href="#错误码与失败恢复" aria-label="Permalink to &quot;错误码与失败恢复&quot;">​</a></h1><p>本页面向 API 调用者和故障处理人员。判断失败需要同时读取 HTTP status、JSON 的 <code>code/message</code> 和发生的接口，不能把一个枚举值套用到所有业务。没有 JSON 的网络/代理错误仍须单独处理。</p><h2 id="通用业务码" tabindex="-1">通用业务码 <a class="header-anchor" href="#通用业务码" aria-label="Permalink to &quot;通用业务码&quot;">​</a></h2><p><code>ResultCodeEnum</code> 定义以下主要分组；实际 Controller 还可能返回自定义数值或默认 201。</p><table tabindex="0"><thead><tr><th>code</th><th>含义</th><th>客户端处理</th></tr></thead><tbody><tr><td>200</td><td>成功</td><td>解包 data；无返回值时 data 可为 null</td></tr><tr><td>201–207</td><td>失败、参数、服务、数据、非法请求、重复提交、仍有子集</td><td>显示服务端短提示；保留输入，不假设等同 HTTP 4xx</td></tr><tr><td>301–304</td><td>账号/验证码相关枚举</td><td>核对具体接口实际返回，验证码错误也可能返回默认 201</td></tr><tr><td>305 / 311</td><td>未登录、未登录或过期</td><td>以当前 HTTP 401 和登录态判定，重新认证</td></tr><tr><td>306–310</td><td>账号不存在/错误/禁用、无权限、用户不存在</td><td>不反复重试；错误密码实现常用 307，权限常用 309</td></tr><tr><td>501–507</td><td>预留应用登录/短信枚举</td><td>仅按已实现接口解释；枚举存在不代表移动应用登录已完整交付</td></tr><tr><td>601 / 602</td><td>token 过期/非法枚举</td><td>当前管理过滤器通常统一返回 HTTP 401/code311，不强依赖这两个枚举</td></tr></tbody></table><p>全局 <code>GlobalExceptionHandler</code> 的参数校验和很多 <code>ServiceException</code> 使用 <code>Result.fail(message)</code>，因此可能 HTTP 200/code201。数据库唯一冲突返回“数据已存在，请勿重复提交”，其他数据库错误返回受控短提示，不向用户展示 SQL。</p><h2 id="http-与业务码的实际组合" tabindex="-1">HTTP 与业务码的实际组合 <a class="header-anchor" href="#http-与业务码的实际组合" aria-label="Permalink to &quot;HTTP 与业务码的实际组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口/失败</th><th>HTTP</th><th>业务 code / 内容</th><th>恢复</th></tr></thead><tbody><tr><td>未登录/失效 JWT 或登录态不存在</td><td>401</td><td>311</td><td>重新登录；不追加 Bearer 前缀</td></tr><tr><td>读取 Redis 登录态基础设施异常</td><td>503</td><td>503</td><td>保持输入，等待服务恢复；不自动认作密码错误</td></tr><tr><td>老管理接口的 <code>AccessDeniedException</code></td><td>可能 200</td><td>309</td><td>检查操作码与平台身份</td></tr><tr><td>本人通知 Controller 拒绝</td><td>403</td><td>309</td><td>不重试其他 owner ID</td></tr><tr><td>低代码 Controller 拒绝</td><td>403</td><td>309</td><td>检查操作码与资源范围</td></tr><tr><td>低代码缺参/格式错误</td><td>400</td><td>400</td><td>修正字段类型或 revision</td></tr><tr><td>低代码版本过期/资源业务失败</td><td>通常 200</td><td>201 + 短提示</td><td>重读并比较，保留用户输入</td></tr><tr><td>文件缺失 / 越权 / 未提交响应的下载故障</td><td>404 / 403 / 502</td><td>201 / 403 / 201</td><td>核对文件归属和存储状态</td></tr><tr><td>业务配置校验 / 权限 / revision 冲突</td><td>400 / 403 / 409</td><td>通常同 status</td><td>修正字段、权限或重读配置</td></tr></tbody></table><p>例如未认证的响应：</p><div class="language-json vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">311</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;用户未登录或登录已过期&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>前端默认响应拦截器会将非成功 code 转成失败；不要只看 Axios 的 HTTP fulfilled 分支。用户提示应简短，详细诊断在受控日志中完成，不向页面显示凭据、SQL 或 provider 请求全文。</p><h2 id="ai-场景读取" tabindex="-1">AI 场景读取 <a class="header-anchor" href="#ai-场景读取" aria-label="Permalink to &quot;AI 场景读取&quot;">​</a></h2><p><code>/ai/scenes/{appKey}/{sceneKey}/render</code> 的错误消息采用 <code>AI_SCENE_READ:&lt;原因&gt;</code>，可携带响应头 <code>X-Request-ID</code> 向运维关联审计事件。</p><table tabindex="0"><thead><tr><th>类别</th><th>HTTP / code</th><th>例子</th><th>恢复</th></tr></thead><tbody><tr><td>未认证/身份无效</td><td>401 / 311</td><td><code>UNAUTHENTICATED</code></td><td>重建有效会话</td></tr><tr><td>权限/租户/资源越权</td><td>403 / 309</td><td><code>BUSINESS_PERMISSION_REQUIRED</code>、<code>TENANT_MISMATCH</code></td><td>申请正确业务授权，不在 context 伪造主体</td></tr><tr><td>app/资源不存在</td><td>404 / 204</td><td><code>APP_NOT_REGISTERED</code>、<code>RESOURCE_NOT_FOUND</code></td><td>核对业务注册与场景键</td></tr><tr><td>context/JSON 无效</td><td>400 / 202</td><td><code>CONTEXT_INVALID</code>、<code>INVALID_REQUEST</code></td><td>按业务允许字段重新构造</td></tr><tr><td>场景/变量注册不可用</td><td>409 / 201</td><td><code>SCENE_UNAVAILABLE</code>、<code>VARIABLE_NOT_REGISTERED</code></td><td>由场景管理员核对发布和变量注册</td></tr><tr><td>值缺失/未声明/无效/输出过长</td><td>422 / 202</td><td><code>MISSING_VARIABLE</code>、<code>UNDECLARED_VALUE</code>、<code>OUTPUT_TOO_LONG</code></td><td>修正上下文或模板</td></tr><tr><td>过大/不支持媒体类型</td><td>413 / 202；415 / 202</td><td><code>REQUEST_TOO_LARGE</code>、<code>UNSUPPORTED_CONTENT</code></td><td>使用未压缩 JSON，限制在16KiB内</td></tr><tr><td>内部失败</td><td>503 / 203</td><td><code>INTERNAL_FAILURE</code></td><td>保留 traceId，运维排查，不泄露 prompt</td></tr></tbody></table><p>这不是供应商模型 HTTP 状态。管理员模型测试的本地响应中可以包含上游 <code>httpStatus=429</code> 或其他失败结果；本地 Controller 返回成功包装不等于模型推理成功。历史 NVIDIA 成功、Poolside 上游429仅是当时验证，不能保证读者的模型账户现时可用。</p><h2 id="微信与批量限制" tabindex="-1">微信与批量限制 <a class="header-anchor" href="#微信与批量限制" aria-label="Permalink to &quot;微信与批量限制&quot;">​</a></h2><p>微信 capability 可以返回未配置或不具备授权能力；authorize/callback 使用 <code>WechatFailure</code> 的实际状态，不能用关闭校验绕过 state/cookie/callbackUri 绑定。当前仅授权发起/state 流程交付，完整绑定登录尚未交付，外部无 AppID 的环境无法进行真实扫码验收。</p><p>用户导入有请求大小/Content-Length 前置限制、XLSX/行数和数据校验。文件导入失败时不把部分失败报告当成全部成功；按<a href="./../features/bulk.html">批量操作</a>显示成功/失败摘要，勿无限重试同一文件。</p><h2 id="排查步骤与源码" tabindex="-1">排查步骤与源码 <a class="header-anchor" href="#排查步骤与源码" aria-label="Permalink to &quot;排查步骤与源码&quot;">​</a></h2><p>先记录接口、HTTP status、业务 code、短 message 和可用 traceId；核对一次当前提交与配置，再按<a href="./../operations/troubleshooting.html">故障排查</a>处理。遇到资源/版本冲突先重读，遇到 503 排基础设施，遇到 401 才重认证。本文不会提供错误码“吞掉后继续成功”的兜底。</p><p>源码：<code>common/common-core/src/main/java/com/xinghuiTec/emues/ResultCodeEnum.java</code>、<code>exception/GlobalExceptionHandler.java</code>；<code>system-framework/src/main/java/com/xinghuiTec/filter/{AuthenticationEntryPointImpl,LoginFilter}.java</code>；<code>system-admin/src/main/java/com/xinghuiTec/controller/{SysOssController,NotificationInboxController,BusinessConfigController,AiSceneReadController}.java</code>、<code>lowcode/{LowcodeFormController,LowcodeRecordController,LowcodeService}.java</code>、<code>ai/prompt/AiSceneReadBoundaryFilter.java</code>、<code>config/UserImportUploadLimitFilter.java</code>。</p>',21)])])}const T=d(r,[["render",i]]);export{E as __pageData,T as default};
